-- DEEP WORK PERMISSIONS
CREATE TABLE IF NOT EXISTS "deep_work_permissions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" TEXT NOT NULL UNIQUE,
  "pattern_work_enabled" BOOLEAN DEFAULT FALSE,
  "structural_work_enabled" BOOLEAN DEFAULT FALSE,
  "identity_work_enabled" BOOLEAN DEFAULT FALSE,
  "foundational_work_enabled" BOOLEAN DEFAULT FALSE,
  "wide_scope_enabled" BOOLEAN DEFAULT FALSE,
  "universal_scope_enabled" BOOLEAN DEFAULT FALSE,
  "experimental_enabled" BOOLEAN DEFAULT FALSE,
  "aggregate_insights_enabled" BOOLEAN DEFAULT TRUE,
  "collective_wisdom_enabled" BOOLEAN DEFAULT FALSE,
  "contribute_to_research" BOOLEAN DEFAULT FALSE,
  "professional_support_confirmed" BOOLEAN DEFAULT FALSE,
  "buddy_system_enabled" BOOLEAN DEFAULT FALSE,
  "emergency_contact_set" BOOLEAN DEFAULT FALSE,
  "consent_given_at" TIMESTAMPTZ,
  "consent_reviewed_at" TIMESTAMPTZ,
  "consent_version" TEXT
);

-- EXPERIMENTAL FLAGS
CREATE TABLE IF NOT EXISTS "experimental_flags" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "content_type" TEXT NOT NULL,
  "content_id" TEXT NOT NULL,
  "flag_type" TEXT NOT NULL,
  "testing_phase" TEXT,
  "user_count" INTEGER DEFAULT 0,
  "positive_reports" INTEGER DEFAULT 0,
  "negative_reports" INTEGER DEFAULT 0,
  "neutral_reports" INTEGER DEFAULT 0,
  "disclaimer_text" TEXT NOT NULL,
  "contraindication_warning" TEXT,
  "professional_consult_recommended" BOOLEAN DEFAULT FALSE,
  "created_at" TIMESTAMPTZ DEFAULT NOW(),
  "promoted_to_established_at" TIMESTAMPTZ,
  "deprecated_at" TIMESTAMPTZ,
  "deprecation_reason" TEXT,
  UNIQUE("content_type", "content_id")
);

-- AI DECISION LOG
CREATE TABLE IF NOT EXISTS "ai_decision_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" TEXT NOT NULL,
  "session_id" TEXT,
  "timestamp" TIMESTAMPTZ DEFAULT NOW(),
  "decision_type" TEXT,
  "decision_made" TEXT,
  "user_context_considered" JSONB,
  "options_evaluated" JSONB,
  "selection_criteria" TEXT,
  "final_reasoning" TEXT,
  "alternatives_available" JSONB,
  "why_not_alternatives" TEXT,
  "user_can_query" BOOLEAN DEFAULT TRUE,
  "explanation_given" BOOLEAN DEFAULT FALSE
);

