-- INDEXES
CREATE INDEX IF NOT EXISTS "idx_scope_log_user" ON "session_scope_log" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_scope_log_session" ON "session_scope_log" ("session_id");
CREATE INDEX IF NOT EXISTS "idx_blend_user" ON "user_technique_blends" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_permissions_user" ON "deep_work_permissions" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_decision_log_user" ON "ai_decision_log" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_aggregate_patterns_cluster" ON "aggregate_patterns" ("condition_cluster");

-- Success message
SELECT 'Meta-Intelligence Layer created. ' ||
       (SELECT COUNT(*) FROM ai_scope_levels) || ' scope levels, ' ||
       (SELECT COUNT(*) FROM ai_depth_levels) || ' depth levels, ' ||
       (SELECT COUNT(*) FROM meta_lens_presets) || ' meta-presets.' AS status;


